<?php
session_name('maison_session');
session_set_cookie_params(86400 * 30);
session_start();

// Se já está autenticada, vai para a plataforma
if (!empty($_SESSION['cliente_id'])) {
    header('Location: plataforma.php');
    exit;
}

require_once 'config.php';
$erro = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $email = strtolower(trim($_POST['email'] ?? ''));
    $password = $_POST['password'] ?? '';

    if ($email && $password) {
        try {
            $pdo = new PDO(
                "mysql:host=" . DB_HOST . ";dbname=" . DB_NAME . ";charset=utf8mb4",
                DB_USER, DB_PASS,
                [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]
            );

            $stmt = $pdo->prepare("SELECT id, password_hash, nome FROM clientes WHERE email = ?");
            $stmt->execute([$email]);
            $cliente = $stmt->fetch(PDO::FETCH_ASSOC);

            if ($cliente && password_verify($password, $cliente['password_hash'])) {
                $_SESSION['cliente_id'] = $cliente['id'];
                $_SESSION['cliente_email'] = $email;
                $_SESSION['cliente_nome'] = $cliente['nome'];

                // Actualizar ultimo acesso
                $pdo->prepare("UPDATE clientes SET ultimo_acesso = NOW() WHERE id = ?")->execute([$cliente['id']]);

                header('Location: plataforma.php');
                exit;
            } else {
                $erro = 'Email ou password incorrectos.';
            }
        } catch (PDOException $e) {
            $erro = 'Erro de ligação. Tenta novamente.';
        }
    } else {
        $erro = 'Preenche todos os campos.';
    }
}
?>
